insert into public.product_sections (product_id, section_type, content, sort_order) select id, 'how_to_use', '["Shake gently. The oil is unfiltered and may show natural sediment.","Take one full dropper (about 1 mL) daily, or as directed by your clinician.","Hold under the tongue for a moment before swallowing, or stir into warm water with honey."]'::jsonb, 0 from public.products where slug = 'blackseed-oil';
insert into public.product_sections (product_id, section_type, content, sort_order) select id, 'faq', '[["Why 4.64%?","Thymoquinone is the most studied constituent of Nigella sativa oil and the clearest marker of seed quality and pressing care. 4.64% is the concentration our Ethiopian seed consistently reaches when pressed cold and released fresh. We print it so you can compare."],["Does it taste strong?","Yes. Honest blackseed oil is peppery, slightly bitter, and aromatic. A bland oil has usually been refined, diluted, or stored too long."],["How long does a bottle last?","At one dropper a day, the 100 mL bottle lasts roughly three months. Refrigerate after opening."]]'::jsonb, 1 from public.products where slug = 'blackseed-oil';
